import yaml
with open('registry.yaml') as f:
    reg = yaml.safe_load(f)
exps = reg.get('experiments', reg)
for k, v in exps.items():
    if isinstance(v, dict):
        s = v.get('status','')
        if s in ('RUNNING','PREPARING','PENDING','QUEUED','ALLOCATED'):
            print(f'{k}: status={s}, conclusion={v.get(\"conclusion\")}')
print('---')
# count by status
from collections import Counter
ctr = Counter()
for k, v in exps.items():
    if isinstance(v, dict):
        ctr[v.get('status','')] += 1
for s, c in sorted(ctr.items()):
    print(f'{s}: {c}')
